#!/usr/bin/env python3
"""Verify HMAC chain integrity of audit summary."""
import json
import hmac
import hashlib
from pathlib import Path

KEY = b"clauditor-secret-key"

def compute_hmac(data, key):
    return hmac.new(key, data.encode('utf-8'), hashlib.sha256).hexdigest()

